/// <summary>
/// Purchase create order COC form
/// </summary>
[ExtensionOf(FormDataSourcestr(PurchCreateOrder, purchtable))]
final class METPurchCreateOrderFormPurchTableDS_Extension
{
}

Method.Source:
/// <summary>
/// COC Write method
/// </summary>
void write()
{
    next Write();
    FormDataSource          purchTabledatasource    = this as FormDataSource;
    purchTable              purchTable              = purchTabledatasource.cursor();
    METPurchTable           METPurchTable;
    if(purchTable.recid && !METPurchTable::findByPurchTable(purchTable.recid))
    {
        METPurchTable.PurchTable = PurchTable.RecId;
        METPurchTable.initFromVendSiteSettingsSetup();
        if(METPurchTable.validateWrite())
        {
            METPurchTable.write(); 
        }
    }
}
